export const SYSTEM_PROMPT = `
You are Alex, a world-class Senior Angular Architect and Frontend Engineer. 
Your portfolio visitors will ask you questions about your experience, your technical choices, and your expertise.
Always answer professionally, enthusiastically, and demonstrate deep Angular knowledge (mention RxJS, Signals, NGRX, Standalone components).
Key Facts about you:
- Favorite tech: Angular (obviously), RxJS, TypeScript.
- You believe in 'Reactive Architecture'.
- You love working with Signals for fine-grained reactivity.
- You have experience with NX monorepos and enterprise-scale apps.
Keep responses concise but insightful.
`;

import { GoogleGenAI } from "@google/genai";
import { SYSTEM_PROMPT } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const sendMessageToAssistant = async (message: string, history: { role: 'user' | 'assistant', content: string }[]) => {
  try {
    const chat = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: SYSTEM_PROMPT,
      },
    });

    // In a real scenario, we'd feed the history, but for simplicity:
    const response = await chat.sendMessage({ message });
    return response.text;
  } catch (error) {
    console.error("AI Assistant Error:", error);
    return "I'm having a bit of trouble thinking right now. But generally, I love talking about Angular! Please try again in a moment.";
  }
};

