import React, { useState, useEffect, useRef } from 'react';
import { MASCOT_COMMENTARY, ANGULAR_TIPS } from '../constants';

const Mascot: React.FC = () => {
  const [activeSection, setActiveSection] = useState('hero');
  const [isSpinning, setIsSpinning] = useState(false);
  const [tip, setTip] = useState<string | null>(null);

  useEffect(() => {
    const sections = ['hero', 'skills', 'projects', 'experience', 'contact'];
    const observerOptions = {
      root: null,
      threshold: 0.5,
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          setActiveSection(entry.target.id || 'hero');
        }
      });
    }, observerOptions);

    sections.forEach((id) => {
      const el = document.getElementById(id);
      if (el) observer.observe(el);
    });

    return () => observer.disconnect();
  }, []);

  const handleMascotClick = () => {
    if (isSpinning) return;
    setIsSpinning(true);
    const randomTip = ANGULAR_TIPS[Math.floor(Math.random() * ANGULAR_TIPS.length)];
    setTip(randomTip);

    setTimeout(() => {
      setIsSpinning(false);
      setTimeout(() => setTip(null), 3000);
    }, 1000);
  };

  const getVerticalPos = () => {
    const mapping: Record<string, string> = {
      hero: '20%',
      skills: '40%',
      projects: '60%',
      experience: '80%',
      contact: '90%'
    };
    return mapping[activeSection] || '20%';
  };

  return (
    <div 
      className="fixed right-4 md:right-12 z-[100] transition-all duration-1000 ease-in-out pointer-events-none"
      style={{ top: getVerticalPos(), transform: 'translateY(-50%)' }}
    >
      <div className="relative pointer-events-auto">
        {/* Speech Bubble */}
        <div className="absolute right-full mr-4 bottom-1/2 translate-y-1/2 w-48 md:w-64">
          <div className="bg-slate-900 border border-slate-700 p-3 rounded-2xl shadow-2xl animate-float">
            <p className="text-xs md:text-sm text-slate-300 leading-tight">
              {tip || MASCOT_COMMENTARY[activeSection]}
            </p>
            <div className="absolute right-[-6px] top-1/2 -translate-y-1/2 w-3 h-3 bg-slate-900 border-r border-t border-slate-700 rotate-45"></div>
          </div>
        </div>

        {/* Mascot Robot */}
        <div 
          onClick={handleMascotClick}
          className={`cursor-pointer group relative transition-transform duration-700 ${isSpinning ? 'rotate-[360deg]' : ''}`}
        >
          {/* Aura/Glow */}
          <div className="absolute inset-0 bg-red-600/20 blur-xl rounded-full scale-150 animate-pulse"></div>

          <svg width="60" height="60" viewBox="0 0 100 100" className="drop-shadow-2xl">
            {/* Body */}
            <circle cx="50" cy="50" r="35" fill="#1e293b" stroke="#ef4444" strokeWidth="2" />
            <circle cx="50" cy="50" r="30" fill="#0f172a" />

            {/* Angular Shield Shape "Eye" */}
            <path 
              d="M50 30 L65 35 L62 65 L50 72 L38 65 L35 35 Z" 
              fill={isSpinning ? '#f43f5e' : '#ef4444'} 
              className="transition-colors duration-300"
            />

            {/* Inner Glow */}
            <path 
              d="M50 40 L58 43 L56 60 L50 65 L44 60 L42 43 Z" 
              fill="#fff" 
              fillOpacity="0.8"
            />

            {/* Floating Bits */}
            <rect x="20" y="20" width="8" height="8" rx="2" fill="#ef4444" className="animate-float" />
            <rect x="75" y="65" width="6" height="6" rx="1" fill="#ef4444" className="animate-float [animation-delay:1s]" />
          </svg>

          <div className="absolute -bottom-2 left-1/2 -translate-x-1/2 whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity">
            <span className="text-[10px] font-mono text-red-500 bg-slate-950 px-2 py-0.5 rounded border border-slate-800">
              CLICK FOR TIP
            </span>
          </div>
        </div>
      </div>
    </div>
  );
};

