import React, { useState, useEffect, useRef, useCallback } from 'react';

type State = 'IDLE' | 'WALKING' | 'CLIMBING' | 'FALLING' | 'DRAGGING' | 'SITTING';

const Mascot: React.FC = () => {
  const [pos, setPos] = useState({ x: 100, y: 100 });
  const [state, setState] = useState<State>('FALLING');
  const [direction, setDirection] = useState<1 | -1>(1); // 1 = right, -1 = left
  const [rotation, setRotation] = useState(0);

  const mascotRef = useRef<HTMLDivElement>(null);
  const stateTimerRef = useRef<number | null>(null);
  const requestRef = useRef<number | null>(null);
  const draggingRef = useRef(false);

  const MASCOT_SIZE = 64;
  const SPEED = 1.5;
  const GRAVITY = 4;

  const updatePhysics = useCallback(() => {
    if (draggingRef.current) return;

    setPos((prev) => {
      let { x, y } = prev;
      const screenWidth = window.innerWidth;
      const screenHeight = window.innerHeight;

      // Floor boundary
      const floor = screenHeight - MASCOT_SIZE;

      if (state === 'FALLING') {
        if (y < floor) {
          y += GRAVITY;
          setRotation(0);
        } else {
          y = floor;
          setState('IDLE');
        }
      } else if (state === 'WALKING') {
        x += SPEED * direction;
        // Wall bounce
        if (x >= screenWidth - MASCOT_SIZE || x <= 0) {
          setDirection(direction === 1 ? -1 : 1);
          // 30% chance to climb if hitting wall
          if (Math.random() < 0.3) {
            setState('CLIMBING');
          }
        }
      } else if (state === 'CLIMBING') {
        y -= SPEED;
        // Rotate mascot for climbing
        setRotation(direction === 1 ? -90 : 90);

        if (y <= 0) {
          y = 0;
          setState('FALLING');
          setRotation(0);
        }
        // Randomly fall off wall
        if (Math.random() < 0.005) {
          setState('FALLING');
          setRotation(0);
        }
      }

      return { x, y };
    });

    requestRef.current = requestAnimationFrame(updatePhysics);
  }, [state, direction]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(updatePhysics);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [updatePhysics]);

  // Logic to change states randomly
  useEffect(() => {
    const changeState = () => {
      if (draggingRef.current) return;

      const states: State[] = ['IDLE', 'WALKING', 'SITTING'];
      const nextState = states[Math.floor(Math.random() * states.length)];

      // If we are on the floor, we can walk or sit
      setPos(p => {
        if (p.y >= window.innerHeight - MASCOT_SIZE) {
          setState(nextState);
          if (nextState === 'WALKING') {
            setDirection(Math.random() > 0.5 ? 1 : -1);
          }
        }
        return p;
      });

      stateTimerRef.current = window.setTimeout(changeState, Math.random() * 5000 + 2000);
    };

    stateTimerRef.current = window.setTimeout(changeState, 3000);
    return () => {
      if (stateTimerRef.current) clearTimeout(stateTimerRef.current);
    };
  }, []);

  const handleMouseDown = (e: React.MouseEvent) => {
    draggingRef.current = true;
    setState('DRAGGING');
    setRotation(0);

    const onMouseMove = (moveEvent: MouseEvent) => {
      setPos({
        x: moveEvent.clientX - MASCOT_SIZE / 2,
        y: moveEvent.clientY - MASCOT_SIZE / 2
      });
    };

    const onMouseUp = () => {
      draggingRef.current = false;
      setState('FALLING');
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
    };

    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mouseup', onMouseUp);
  };

  return (
    <div
      ref={mascotRef}
      onMouseDown={handleMouseDown}
      className="fixed z-[9999] cursor-grab active:cursor-grabbing select-none transition-transform duration-75"
      style={{
        left: pos.x,
        top: pos.y,
        width: MASCOT_SIZE,
        height: MASCOT_SIZE,
        transform: `rotate(${rotation}deg) scaleX(${direction})`,
        pointerEvents: 'auto'
      }}
    >
      <div className={`relative w-full h-full transition-all ${state === 'SITTING' ? 'translate-y-2' : ''}`}>
        {/* Shadow */}
        <div className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-8 h-2 bg-black/20 blur-md rounded-full"></div>

        {/* Shimeji Body (Angular Robot) */}
        <svg viewBox="0 0 100 100" className={`w-full h-full drop-shadow-lg ${state === 'WALKING' ? 'animate-bounce' : ''} ${state === 'FALLING' ? 'scale-y-110' : ''}`}>
          {/* Main Chassis */}
          <rect x="25" y="35" width="50" height="45" rx="12" fill="#1e293b" stroke="#ef4444" strokeWidth="3" />
          <rect x="30" y="40" width="40" height="35" rx="8" fill="#0f172a" />

          {/* Eye / Shield */}
          <path 
            d="M50 45 L60 48 L58 65 L50 70 L42 65 L40 48 Z" 
            fill="#ef4444" 
            className={state === 'IDLE' ? 'animate-pulse' : ''}
          />

          {/* Antenna */}
          <line x1="50" y1="35" x2="50" y2="20" stroke="#ef4444" strokeWidth="3" />
          <circle cx="50" cy="20" r="5" fill="#ef4444" />

          {/* Hands/Feet based on state */}
          {state === 'CLIMBING' ? (
             <>
               <circle cx="20" cy="45" r="6" fill="#1e293b" />
               <circle cx="80" cy="45" r="6" fill="#1e293b" />
             </>
          ) : (
            <>
              <rect x="30" y="75" width="10" height="12" rx="4" fill="#1e293b" />
              <rect x="60" y="75" width="10" height="12" rx="4" fill="#1e293b" />
            </>
          )}

          {/* Interaction Indicators */}
          {state === 'DRAGGING' && (
             <text x="50" y="15" textAnchor="middle" fill="#ef4444" fontSize="20" fontWeight="bold">!</text>
          )}
        </svg>
      </div>
    </div>
  );
};

