  // Frame animation loop
  useEffect(() => {
    const interval = setInterval(() => {
      setFrame(f => (f + 1) % 4);
    }, 150);
    return () => clearInterval(interval);
  }, []);

  const updatePhysics = useCallback(() => {
    if (draggingRef.current) return;

    setPos((prev) => {
      let { x, y } = prev;
      const screenWidth = window.innerWidth;
      const screenHeight = window.innerHeight;
      const floor = screenHeight - MASCOT_SIZE;

      if (state === 'FALLING') {
        if (y < floor) {
          y += GRAVITY;
        } else {
          y = floor;
          setState('IDLE');
          if (Math.random() < 0.05) {
            setIsSuperSaiyan(true);
            setAuraVisible(true);
          }
        }
      } else if (state === 'WALKING') {
        x += (isSuperSaiyan ? SPEED * 2 : SPEED) * direction;
        if (x >= screenWidth - MASCOT_SIZE || x <= 0) {
          setDirection(direction === 1 ? -1 : 1);
          if (Math.random() < 0.2) setState('CLIMBING');
        }
      } else if (state === 'CLIMBING') {
        y -= SPEED;
        if (y <= 0) {
          y = 0;
          setState('FALLING');
        }
        if (Math.random() < 0.005) {
          setState('FALLING');
        }
      } else if (state === 'CHARGING') {
        // Subtle vibration handled by CSS
      }

      return { x, y };
    });

    requestRef.current = requestAnimationFrame(updatePhysics);
  }, [state, direction, isSuperSaiyan]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(updatePhysics);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [updatePhysics]);

  useEffect(() => {
    const changeState = () => {
      if (draggingRef.current) return;
      const states: State[] = ['IDLE', 'WALKING', 'CHARGING'];
      const nextState = states[Math.floor(Math.random() * states.length)];

      setPos(p => {
        if (p.y >= window.innerHeight - MASCOT_SIZE) {
          setState(nextState);
          if (nextState === 'WALKING') setDirection(Math.random() > 0.5 ? 1 : -1);
          if (nextState === 'CHARGING') {
            setIsSuperSaiyan(true);
            setAuraVisible(true);
            setTimeout(() => setAuraVisible(false), 2000);
          }
        }
        return p;
      });

      stateTimerRef.current = window.setTimeout(changeState, Math.random() * 5000 + 3000);
    };

    stateTimerRef.current = window.setTimeout(changeState, 3000);
    return () => { if (stateTimerRef.current) clearTimeout(stateTimerRef.current); };
  }, []);

  const handleMouseDown = (e: React.MouseEvent) => {
    draggingRef.current = true;
    setState('DRAGGING');
    setIsSuperSaiyan(true);
    setAuraVisible(true);

    const onMouseMove = (moveEvent: MouseEvent) => {
      setPos({
        x: moveEvent.clientX - MASCOT_SIZE / 2,
        y: moveEvent.clientY - MASCOT_SIZE / 2
      });
    };

    const onMouseUp = () => {
      draggingRef.current = false;
      setState('FALLING');
      setAuraVisible(false);
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
    };

    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mouseup', onMouseUp);
  };

  const gokuSVG = useMemo(() => {
    const hairColor = isSuperSaiyan ? "#F0D500" : "#0A0A0A";
    const hairStroke = isSuperSaiyan ? "#FF8C00" : "#222";
    const eyeColor = isSuperSaiyan ? "#2ECC71" : "#000";

    return (
      <svg viewBox="0 0 100 100" className={`w-full h-full drop-shadow-2xl`}>
        {/* Ki Aura Effect (only when charging or dragged) */}
        {(auraVisible || state === 'CHARGING') && (
          <g className="animate-pulse opacity-60">
            <path 
              d="M50 10 L80 40 L90 80 L50 95 L10 80 L20 40 Z" 
              fill={isSuperSaiyan ? "#F0D500" : "#3498DB"} 
              filter="blur(8px)"
            />
          </g>
        )}

        {/* Hair - Detailed Multi-spike */}
        <path 
          d="M20 45 C15 35 5 30 10 20 C15 15 25 20 30 10 C35 5 45 10 50 5 C55 10 65 5 70 10 C75 20 85 15 90 20 C95 30 85 35 80 45 L85 55 L75 75 L25 75 L15 55 Z" 
          fill={hairColor} 
          stroke={hairStroke} 
          strokeWidth="1.5"
        />

        {/* Detailed Face */}
        <path d="M32 48 C32 65 50 85 68 48" fill="#FFDBAC" />

        {/* Expressive Eyes */}
        <g transform={`translate(0, ${state === 'CHARGING' ? -1 : 0})`}>
          <path d="M38 52 Q43 50 48 53" stroke="black" strokeWidth="1.5" fill="none" />
          <path d="M52 53 Q57 50 62 52" stroke="black" strokeWidth="1.5" fill="none" />
          <circle cx="43" cy="54" r="1.5" fill={eyeColor} />
          <circle cx="57" cy="54" r="1.5" fill={eyeColor} />

          {/* Eyebrows */}
          <path d="M36 50 L48 48" stroke={hairColor} strokeWidth="2.5" />
          <path d="M52 48 L64 50" stroke={hairColor} strokeWidth="2.5" />
        </g>

        {/* Mouth */}
        {state === 'CHARGING' ? (
          <path d="M45 68 Q50 75 55 68" fill="#600" />
        ) : (
          <path d="M47 68 Q50 70 53 68" stroke="black" strokeWidth="0.5" fill="none" />
        )}

        {/* Body - Orange Gi */}
        <path d="M35 75 L65 75 L75 98 L25 98 Z" fill="#E64A19" stroke="#111" strokeWidth="1" />

        {/* Blue undershirt & belt */}
        <path d="M40 75 L60 75 L65 82 L35 82 Z" fill="#1A237E" />
        <path d="M35 88 L65 88 L65 92 L35 92 Z" fill="#1A237E" />

        {/* Kan-ji Symbol */}
        <circle cx="50" cy="81" r="5" fill="white" stroke="black" strokeWidth="0.5" />
        <path d="M48 79 L52 83 M52 79 L48 83" stroke="black" strokeWidth="1" />

        {/* Arms/Legs Animation */}
        {state === 'WALKING' && (
          <g>
            <path d={frame % 2 === 0 ? "M25 90 L15 100" : "M25 90 L20 100"} stroke="#E64A19" strokeWidth="8" strokeLinecap="round" />
            <path d={frame % 2 === 0 ? "M75 90 L85 100" : "M75 90 L80 100"} stroke="#E64A19" strokeWidth="8" strokeLinecap="round" />
          </g>
        )}

        {state === 'FALLING' && (
          <g>
            <path d="M20 70 L5 60" stroke="#FFDBAC" strokeWidth="6" strokeLinecap="round" />
            <path d="M80 70 L95 60" stroke="#FFDBAC" strokeWidth="6" strokeLinecap="round" />
          </g>
        )}

        {state === 'CLIMBING' && (
          <g>
            <path d="M30 45 L20 30" stroke="#FFDBAC" strokeWidth="6" strokeLinecap="round" />
            <path d="M70 45 L80 30" stroke="#FFDBAC" strokeWidth="6" strokeLinecap="round" />
          </g>
        )}
      </svg>
    );
  }, [state, isSuperSaiyan, frame, auraVisible]);

  return (
    <div
      ref={mascotRef}
      onMouseDown={handleMouseDown}
      className={`fixed z-[9999] cursor-grab active:cursor-grabbing select-none will-change-transform ${state === 'CHARGING' ? 'animate-bounce' : ''}`}
      style={{
        left: pos.x,
        top: pos.y,
        width: MASCOT_SIZE,
        height: MASCOT_SIZE,
        transform: `scaleX(${direction})`,
        transition: state === 'DRAGGING' ? 'none' : 'transform 0.1s linear, left 0.1s linear, top 0.1s linear'
      }}
    >
      <div className="relative w-full h-full">
        {gokuSVG}

        {/* Action Callout (Rare) */}
        {state === 'CHARGING' && (
          <div className="absolute -top-12 left-1/2 -translate-x-1/2 bg-yellow-400 border-2 border-orange-600 px-3 py-1 rounded-md anime-font text-orange-800 text-sm whitespace-nowrap animate-bounce">
            HAAAAAA!
          </div>
        )}
      </div>
    </div>
  );
};

