import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';

type CatState = 'IDLE' | 'WALKING' | 'CLIMBING' | 'FALLING' | 'DRAGGING' | 'SCRATCHING' | 'PLAYING_DEAD';

interface CatProps {
  id: number;
  color: string;
  initialX: number;
  initialY: number;
}

const Cat: React.FC<CatProps> = ({ color, initialX, initialY }) => {
  const [pos, setPos] = useState({ x: initialX, y: initialY });
  const [state, setState] = useState<CatState>('FALLING');
  const [direction, setDirection] = useState<1 | -1>(1);
  const [frame, setFrame] = useState(0);

  const draggingRef = useRef(false);
  const requestRef = useRef<number | null>(null);
  const stateTimerRef = useRef<number | null>(null);

  const SIZE = 70;
  const SPEED = 1.8 + Math.random();
  const GRAVITY = 5;

  // Frame animation
  useEffect(() => {
    const interval = setInterval(() => {
      setFrame(f => (f + 1) % 4);
    }, 150);
    return () => clearInterval(interval);
  }, []);

  const updatePhysics = useCallback(() => {
    if (draggingRef.current) return;

    setPos((prev) => {
      let { x, y } = prev;
      const sw = window.innerWidth;
      const sh = window.innerHeight;
      const floor = sh - SIZE;

      if (state === 'FALLING') {
        if (y < floor) y += GRAVITY;
        else {
          y = floor;
          setState('IDLE');
        }
      } else if (state === 'WALKING') {
        x += SPEED * direction;
        if (x >= sw - SIZE || x <= 0) {
          setDirection(direction === 1 ? -1 : 1);
          if (Math.random() < 0.2) setState('CLIMBING');
        }
      } else if (state === 'CLIMBING') {
        y -= SPEED;
        if (y <= 0) {
          y = 0;
          setState('FALLING');
        }
        if (Math.random() < 0.01) setState('FALLING');
      }

      return { x, y };
    });

    requestRef.current = requestAnimationFrame(updatePhysics);
  }, [state, direction]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(updatePhysics);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [updatePhysics]);

  useEffect(() => {
    const changeStateRandomly = () => {
      if (draggingRef.current || state === 'SCRATCHING' || state === 'PLAYING_DEAD') return;

      const states: CatState[] = ['IDLE', 'WALKING', 'IDLE'];
      const next = states[Math.floor(Math.random() * states.length)];

      setPos(p => {
        if (p.y >= window.innerHeight - SIZE) {
          setState(next);
          if (next === 'WALKING') setDirection(Math.random() > 0.5 ? 1 : -1);
        }
        return p;
      });

      stateTimerRef.current = window.setTimeout(changeStateRandomly, 3000 + Math.random() * 4000);
    };

    stateTimerRef.current = window.setTimeout(changeStateRandomly, 2000);
    return () => { if (stateTimerRef.current) clearTimeout(stateTimerRef.current); };
  }, [state]);

  const handleMouseDown = (e: React.MouseEvent) => {
    draggingRef.current = true;
    setState('DRAGGING');

    const onMouseMove = (moveEvent: MouseEvent) => {
      setPos({
        x: moveEvent.clientX - SIZE / 2,
        y: moveEvent.clientY - SIZE / 2
      });
    };

    const onMouseUp = () => {
      draggingRef.current = false;
      setState('FALLING');
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
    };

    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mouseup', onMouseUp);
  };

  const handleInteraction = () => {
    if (state === 'DRAGGING') return;

    const roll = Math.random();
    if (roll < 0.3) {
      setState('SCRATCHING');
      setTimeout(() => setState('IDLE'), 800);
    } else if (roll < 0.5) {
      setState('PLAYING_DEAD');
      setTimeout(() => setState('IDLE'), 2500);
    }
  };

  const catSVG = useMemo(() => {
    const isPlayingDead = state === 'PLAYING_DEAD';
    const isScratching = state === 'SCRATCHING';

    return (
      <svg viewBox="0 0 100 100" className="w-full h-full drop-shadow-lg">
        <g transform={isPlayingDead ? 'translate(0, 20) rotate(180, 50, 50)' : ''}>
          {/* Tail */}
          <path 
            d="M20 70 Q10 60 15 50" 
            fill="none" 
            stroke={color} 
            strokeWidth="6" 
            strokeLinecap="round"
            className={state === 'WALKING' ? 'animate-pulse' : ''}
          />

          {/* Body */}
          <ellipse cx="50" cy="70" rx="25" ry="18" fill={color} />

          {/* Head */}
          <circle cx="70" cy="55" r="18" fill={color} />

          {/* Ears */}
          <path d="M60 42 L65 30 L72 40 Z" fill={color} />
          <path d="M78 40 L85 30 L90 42 Z" fill={color} />

          {/* Eyes */}
          <circle cx="65" cy="52" r="2.5" fill="black" />
          <circle cx="82" cy="52" r="2.5" fill="black" />

          {/* Nose */}
          <path d="M72 58 L75 60 L78 58" fill="none" stroke="pink" strokeWidth="1" />

          {/* Legs */}
          {state === 'WALKING' && (
            <g>
              <line x1="40" y1="85" x2={frame % 2 === 0 ? "35" : "45"} y2="95" stroke={color} strokeWidth="5" />
              <line x1="60" y1="85" x2={frame % 2 === 0 ? "65" : "55"} y2="95" stroke={color} strokeWidth="5" />
            </g>
          )}

          {/* Scratching Claws */}
          {isScratching && (
            <g className="animate-ping">
              <path d="M85 50 L95 40 M85 55 L95 55 M85 60 L95 70" stroke="white" strokeWidth="2" />
            </g>
          )}
        </g>
      </svg>
    );
  }, [state, color, frame]);

  return (
    <div
      onMouseDown={handleMouseDown}
      onClick={handleInteraction}
      className={`fixed z-[9999] cursor-grab active:cursor-grabbing select-none will-change-transform ${state === 'SCRATCHING' ? 'vibrate' : ''}`}
      style={{
        left: pos.x,
        top: pos.y,
        width: SIZE,
        height: SIZE,
        transform: `scaleX(${direction})`,
        transition: state === 'DRAGGING' ? 'none' : 'transform 0.1s linear, left 0.1s linear, top 0.1s linear'
      }}
    >
      {catSVG}
    </div>
  );
};

export default Cat;

