      if (state === 'FALLING') {
        if (y < floor) y += GRAVITY;
        else {
          y = floor;
          setState('IDLE');
        }
      } else if (state === 'WALKING') {
        x += SPEED * direction;
        // Bounce off walls and potentially climb
        if (x >= sw - SIZE || x <= 0) {
          x = x <= 0 ? 0 : sw - SIZE;
          setDirection(direction === 1 ? -1 : 1);
          if (Math.random() < 0.4) setState('CLIMBING');
        }
      } else if (state === 'CLIMBING') {
        y -= SPEED * 0.8;
        // Rotate logic handled in SVG transform
        if (y <= 0) {
          y = 0;
          setState('FALLING');
        }
        // Randomly drop or turn back
        if (Math.random() < 0.005) setState('FALLING');
      }

      return { x, y };
    });

    requestRef.current = requestAnimationFrame(updatePhysics);
  }, [state, direction, SPEED, isLegendary]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(updatePhysics);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [updatePhysics]);

  useEffect(() => {
    const changeStateRandomly = () => {
      if (draggingRef.current || state === 'SCRATCHING' || state === 'PLAYING_DEAD') return;

      const states: CatState[] = ['IDLE', 'WALKING', 'SITTING', 'WALKING'];
      const next = states[Math.floor(Math.random() * states.length)];

      setPos(p => {
        // Only allow state changes if on a boundary or idle
        if (p.y >= window.innerHeight - SIZE || state === 'IDLE') {
          setState(next);
          if (next === 'WALKING') setDirection(Math.random() > 0.5 ? 1 : -1);
        }
        return p;
      });

      stateTimerRef.current = window.setTimeout(changeStateRandomly, 2000 + Math.random() * 5000);
    };

    stateTimerRef.current = window.setTimeout(changeStateRandomly, 2000);
    return () => { if (stateTimerRef.current) clearTimeout(stateTimerRef.current); };
  }, [state]);

  const handleMouseDown = (e: React.MouseEvent) => {
    e.stopPropagation();
    draggingRef.current = true;
    setState('DRAGGING');

    const onMouseMove = (moveEvent: MouseEvent) => {
      setPos({
        x: moveEvent.clientX - SIZE / 2,
        y: moveEvent.clientY - SIZE / 2
      });
    };

    const onMouseUp = () => {
      draggingRef.current = false;
      setState('FALLING');
      window.removeEventListener('mousemove', onMouseMove);
