          ) : isScratching ? (
            <>
              <path d="M68 50 L74 54" stroke="black" strokeWidth="3" />
              <path d="M82 54 L88 50" stroke="black" strokeWidth="3" />
            </>
          ) : (
            <>
              <circle cx="72" cy="52" r="3" fill="black" />
              <circle cx="88" cy="52" r="3" fill="black" />
              {/* Eye sparkle */}
              <circle cx="73" cy="51" r="1" fill="white" />
              <circle cx="89" cy="51" r="1" fill="white" />
