        )}

        <g transform={`rotate(${rotation}, 50, 50) scale(${direction}, 1) translate(${direction === -1 ? -100 : 0}, 0)`}>
          {/* Tail */}
          <path 
            d={`M30 70 Q20 ${60 + tailWiggle} 25 ${40 + tailWiggle}`} 
            fill="none" 
            stroke={color} 
            strokeWidth="8" 
            strokeLinecap="round"
          />

          {/* Back Legs */}
          <g>
            {isClimbing ? (
               // Vertical climbing leg movement
               <>
                 <path d={`M40 75 Q30 85 ${35 + climbLegWiggle} 90`} stroke={color} strokeWidth="7" fill="none" strokeLinecap="round" />
                 <path d={`M50 75 Q40 85 ${45 - climbLegWiggle} 90`} stroke={color} strokeWidth="7" fill="none" strokeLinecap="round" opacity="0.6" />
