               </>
            )}
          </g>

          {/* Body */}
          <ellipse cx="55" cy="70" rx="28" ry="20" fill={color} />

          {/* Front Legs */}
          <g>
            {isClimbing ? (
               // Pulling up animation
               <>
                 <path d={`M70 75 Q80 85 ${75 + climbLegWiggle} 90`} stroke={color} strokeWidth="7" fill="none" strokeLinecap="round" />
                 <path d={`M80 75 Q90 85 ${85 - climbLegWiggle} 90`} stroke={color} strokeWidth="7" fill="none" strokeLinecap="round" opacity="0.6" />
