    if (draggingRef.current) return;

    setPos((prev) => {
      let { x, y } = prev;
      const sw = window.innerWidth;
      const sh = window.innerHeight;
      const screenFloor = sh - SIZE;
      let currentFloor = screenFloor;

      // 1. Detect Local Floor (Platform)
      // Check if we are currently standing on top of an element
      surfacesRef.current.forEach(rect => {
