              blocked = true;
              break;
            }
            // Hit right side moving left
            if (direction === -1 && nextX <= rect.right && x >= rect.right) {
              x = rect.right;
              blocked = true;
              break;
            }
          }
        }

        // Screen boundary check
        if (!blocked && (nextX >= sw - SIZE || nextX <= 0)) {
          x = nextX <= 0 ? 0 : sw - SIZE;
          blocked = true;
        }

        if (blocked) {
          if (Math.random() < 0.7) {
            setState('CLIMBING');
          } else {
            setDirection(direction === 1 ? -1 : 1);
          }
        } else {
          x = nextX;
          // Walk off edge detection
          if (y < currentFloor - 10) {
