      } else if (state === 'CHASING_TAIL') {
        x += Math.sin(frame) * 3;
        y += Math.cos(frame) * 3;
      }

      return { x, y };
    });

    requestRef.current = requestAnimationFrame(updatePhysics);
  }, [state, direction, currentSpeed, frame]);

