      onMouseDown={handleMouseDown}
      onClick={handleInteraction}
      className={`fixed z-[9999] cursor-grab active:cursor-grabbing select-none will-change-transform ${state === 'SCRATCHING' || state === 'CHASING_TAIL' || state === 'WIGGLING' ? 'vibrate' : ''}`}
      style={{
        left: pos.x,
        top: pos.y,
        width: SIZE,
        height: SIZE,
        transform: isZoomed ? 'scale(1.25)' : 'scale(1)',
        transition: ['DRAGGING', 'CHASING_TAIL', 'POUNCING'].includes(state) 
          ? 'transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275)' 
          : 'left 0.1s linear, top 0.1s linear, transform 0.3s ease-out'
      }}
    >
      <div className="relative w-full h-full group">
        {catSVG}

        <div className="absolute -top-10 left-1/2 -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity text-[10px] font-black text-white bg-orange-600 px-3 py-1 rounded-full pointer-events-none anime-font italic tracking-widest shadow-lg border border-white/20 whitespace-nowrap">
          {state === 'POUNCING' ? 'NYA BLAST!' : 
           state === 'SNIFFING' ? 'QUERYING...' : 
           state === 'STRETCHING' ? 'REFACTORING' : 
           state === 'WIGGLING' ? 'EXCITED!' : 
           state === 'CLIMBING' ? 'ELEMENT CLIMB!' : 'NEKO ARCHITECT'}
        </div>
      </div>
    </div>
  );
};

export default Cat;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';

type CatState = 
  | 'IDLE' | 'WALKING' | 'CLIMBING' | 'FALLING' | 'DRAGGING' 
  | 'SCRATCHING' | 'PLAYING_DEAD' | 'SITTING' | 'GROOMING' 
  | 'NAPPING' | 'CHASING_TAIL' | 'POUNCING' | 'SNIFFING' 
  | 'STRETCHING' | 'WIGGLING';

interface CatProps {
  id: number;
  color: string;
  initialX: number;
  initialY: number;
}

const Cat: React.FC<CatProps> = ({ color, initialX, initialY }) => {
  const [pos, setPos] = useState({ x: initialX, y: initialY });
  const [state, setState] = useState<CatState>('FALLING');
  const [direction, setDirection] = useState<1 | -1>(1);
  const [frame, setFrame] = useState(0);
  const [isLegendary, setIsLegendary] = useState(Math.random() > 0.9);
  const [isZoomed, setIsZoomed] = useState(false);

  const draggingRef = useRef(false);
  const requestRef = useRef<number | null>(null);
  const stateTimerRef = useRef<number | null>(null);
  const surfacesRef = useRef<DOMRect[]>([]);

  const SIZE = 90;
  const SPEED_BASE = (isLegendary ? 4.0 : 2.8) + Math.random();
  const [currentSpeed] = useState(SPEED_BASE);
  const GRAVITY = 7;

  // Find all elements that can act as platforms or walls
  const updateSurfaces = useCallback(() => {
    const elements = document.querySelectorAll('h1, h2, h3, button, a, img, .group, .p-8, .p-5');
    const rects: DOMRect[] = [];
    elements.forEach((el) => {
      const rect = el.getBoundingClientRect();
      if (rect.width > 20 && rect.height > 20) {
        rects.push(rect);
      }
    });
    surfacesRef.current = rects;
  }, []);

  useEffect(() => {
    updateSurfaces();
    window.addEventListener('resize', updateSurfaces);
    window.addEventListener('scroll', updateSurfaces);
    const interval = setInterval(updateSurfaces, 3000); // Re-scan periodically for dynamic content
    return () => {
      window.removeEventListener('resize', updateSurfaces);
      window.removeEventListener('scroll', updateSurfaces);
      clearInterval(interval);
    };
  }, [updateSurfaces]);

  // Frame animation loop
  useEffect(() => {
    const interval = setInterval(() => {
      setFrame(f => (f + 1) % 12);
    }, 70);
    return () => clearInterval(interval);
  }, []);

  const updatePhysics = useCallback(() => {
    if (draggingRef.current) return;

    setPos((prev) => {
      let { x, y } = prev;
      const sw = window.innerWidth;
      const sh = window.innerHeight;
      const screenFloor = sh - SIZE;
      let currentFloor = screenFloor;

      // 1. Detect Local Floor (Platform)
      surfacesRef.current.forEach(rect => {
        if (x + SIZE/2 > rect.left && x + SIZE/2 < rect.right) {
          const surfaceTop = rect.top - SIZE + 5;
          if (y >= surfaceTop - 10 && y <= surfaceTop + 10) {
            currentFloor = surfaceTop;
          }
        }
      });

      if (state === 'FALLING') {
        let landed = false;
        for (const rect of surfacesRef.current) {
          const surfaceTop = rect.top - SIZE + 5;
          if (y + GRAVITY >= surfaceTop && y < surfaceTop && x + SIZE/2 > rect.left && x + SIZE/2 < rect.right) {
            y = surfaceTop;
            landed = true;
            break;
          }
        }

        if (landed || y >= screenFloor) {
          y = landed ? y : screenFloor;
          setState('IDLE');
        } else {
          y += GRAVITY;
        }
      } else if (state === 'WALKING' || state === 'POUNCING') {
        const speedMult = state === 'POUNCING' ? 2.5 : 1;
        const nextX = x + currentSpeed * direction * speedMult;

        let blocked = false;
        for (const rect of surfacesRef.current) {
          const isAtSameHeight = y + SIZE > rect.top + 10 && y < rect.bottom - 10;
          if (isAtSameHeight) {
            if (direction === 1 && nextX + SIZE >= rect.left && x + SIZE <= rect.left) {
              x = rect.left - SIZE;
              blocked = true;
              break;
            }
            if (direction === -1 && nextX <= rect.right && x >= rect.right) {
              x = rect.right;
              blocked = true;
              break;
            }
          }
        }

        if (!blocked && (nextX >= sw - SIZE || nextX <= 0)) {
          x = nextX <= 0 ? 0 : sw - SIZE;
          blocked = true;
        }

        if (blocked) {
          if (Math.random() < 0.7) {
            setState('CLIMBING');
          } else {
            setDirection(direction === 1 ? -1 : 1);
          }
        } else {
          x = nextX;
          if (y < currentFloor - 10) {
            setState('FALLING');
          }
        }
      } else if (state === 'CLIMBING') {
        y -= currentSpeed * 0.8;

        let reachedTop = false;
        for (const rect of surfacesRef.current) {
          const isAtRectX = (Math.abs(x + SIZE - rect.left) < 5) || (Math.abs(x - rect.right) < 5);
          if (isAtRectX && y <= rect.top - SIZE + 5) {
            y = rect.top - SIZE + 5;
            reachedTop = true;
            break;
          }
        }

        if (reachedTop || y <= 0) {
          y = Math.max(0, y);
          setState('WALKING');
          setDirection(direction);
        }
        if (Math.random() < 0.006) setState('FALLING');
      } else if (state === 'CHASING_TAIL') {
        x += Math.sin(frame) * 3;
        y += Math.cos(frame) * 3;
      }

      return { x, y };
    });

    requestRef.current = requestAnimationFrame(updatePhysics);
  }, [state, direction, currentSpeed, frame]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(updatePhysics);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [updatePhysics]);

  useEffect(() => {
    const changeStateRandomly = () => {
      const lockedStates: CatState[] = ['SCRATCHING', 'PLAYING_DEAD', 'CLIMBING', 'CHASING_TAIL', 'POUNCING', 'STRETCHING', 'WIGGLING', 'SNIFFING'];
      if (draggingRef.current || lockedStates.includes(state)) return;

      const actionStates: CatState[] = ['WALKING', 'WALKING', 'WALKING', 'WALKING', 'WALKING', 'WALKING', 'CHASING_TAIL'];
      const restStates: CatState[] = ['IDLE', 'SITTING', 'GROOMING', 'NAPPING'];

      let specialty: CatState | null = null;
      if (color === '#F59E0B' || color === '#D97706') specialty = 'POUNCING';
      else if (color === '#4B5563' || color === '#8B4513') specialty = 'SNIFFING';
      else if (color === '#1F2937') specialty = 'STRETCHING';
      else if (color === '#E5E7EB' || color === '#FFDAB9') specialty = 'WIGGLING';

      if (specialty && Math.random() < 0.3) {
        actionStates.push(specialty);
      }

      const allPossible = [...actionStates, ...restStates];
      const next = allPossible[Math.floor(Math.random() * allPossible.length)];

      setState(next);
      if (next === 'WALKING') setDirection(Math.random() > 0.5 ? 1 : -1);

      if (next === 'GROOMING') setTimeout(() => setState('IDLE'), 2000);
      if (next === 'NAPPING') setTimeout(() => setState('IDLE'), 5000);
      if (next === 'CHASING_TAIL') setTimeout(() => setState('IDLE'), 1500);
      if (next === 'POUNCING') setTimeout(() => setState('WALKING'), 1200);
      if (next === 'SNIFFING') setTimeout(() => setState('WALKING'), 2000);
      if (next === 'STRETCHING') setTimeout(() => setState('WALKING'), 2500);
      if (next === 'WIGGLING') setTimeout(() => setState('WALKING'), 1500);

      stateTimerRef.current = window.setTimeout(changeStateRandomly, 2000 + Math.random() * 3000);
    };

    stateTimerRef.current = window.setTimeout(changeStateRandomly, 1000);
    return () => { if (stateTimerRef.current) clearTimeout(stateTimerRef.current); };
  }, [state, color]);

  const handleMouseDown = (e: React.MouseEvent) => {
    e.stopPropagation();
    draggingRef.current = true;
    setState('DRAGGING');

    const onMouseMove = (moveEvent: MouseEvent) => {
      setPos({
        x: moveEvent.clientX - SIZE / 2,
        y: moveEvent.clientY - SIZE / 2
      });
    };

    const onMouseUp = () => {
      draggingRef.current = false;
      setState('FALLING');
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
    };

    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mouseup', onMouseUp);
  };

  const handleInteraction = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (state === 'DRAGGING') return;

    setIsZoomed(true);
    setTimeout(() => setIsZoomed(false), 1000);

    const roll = Math.random();
    if (roll < 0.15) {
      setState('SCRATCHING');
      setTimeout(() => setState('IDLE'), 1000);
    } else if (roll < 0.35) {
      setState('PLAYING_DEAD');
      setTimeout(() => setState('IDLE'), 4000);
    } else {
      setPos(p => ({ ...p, y: p.y - 50 }));
      setState('FALLING');
    }
  };

  const catSVG = useMemo(() => {
    const isPlayingDead = state === 'PLAYING_DEAD';
    const isScratching = state === 'SCRATCHING';
    const isClimbing = state === 'CLIMBING';
    const isWalking = state === 'WALKING';
    const isGrooming = state === 'GROOMING';
    const isNapping = state === 'NAPPING';
    const isChasingTail = state === 'CHASING_TAIL';
    const isPouncing = state === 'POUNCING';
    const isSniffing = state === 'SNIFFING';
    const isStretching = state === 'STRETCHING';
    const isWiggling = state === 'WIGGLING';

    let rotation = 0;
    if (isClimbing) rotation = direction === 1 ? -90 : 90;
    if (isPlayingDead) rotation = 180;
    if (isChasingTail) rotation = frame * 30;

    const tailWiggle = Math.sin(frame * 0.4) * (isWiggling ? 30 : 15);
    const walkLegWiggle = Math.sin(frame * 0.8) * 15;
    const climbLegWiggle = Math.sin(frame * 1.5) * 10;
    const breathing = (isNapping || isSniffing) ? Math.sin(frame * 0.2) * 2 : 0;

    const bodyScaleY = isStretching ? 0.7 : 1;
    const bodyTranslateY = isStretching ? 10 : 0;

    const headTranslateY = isSniffing ? 12 : 0;
    const headTranslateX = isSniffing ? -5 : 0;

    return (
      <svg viewBox="0 0 100 100" className={`w-full h-full pointer-events-none drop-shadow-md ${isWiggling ? 'animate-pulse' : ''}`}>
        {isLegendary && (
          <circle cx="50" cy="50" r="48" fill="rgba(248, 91, 26, 0.15)" className="animate-pulse blur-xl" />
        )}

        {/* Particles */}
        <g transform={`scale(${direction}, 1) translate(${direction === -1 ? -100 : 0}, 0)`}>
          {isPouncing && [1, 2, 3].map(i => (
            <circle 
              key={`pounce-spark-${i}`} 
              cx={20 - i * 5} 
              cy={70 + (i % 2 ? -10 : 10)} 
              r="2" 
              fill="white" 
              className="animate-spark-drift" 
              style={{ animationDelay: `${i * 0.1}s` }} 
            />
          ))}
          {isClimbing && [1, 2, 3].map(i => (
            <circle 
              key={`climb-dust-${i}`} 
              cx={70 + (i * 5)} 
              cy={90} 
              r="1.5" 
              fill="#F85B1A" 
              opacity="0.6"
              className="animate-float-up" 
              style={{ animationDelay: `${i * 0.2}s` }} 
            />
          ))}
        </g>

        <g transform={`rotate(${rotation}, 50, 50) scale(${direction}, 1) translate(${direction === -1 ? -100 : 0}, 0)`}>
          {/* Tail */}
          <path 
            d={`M30 75 Q15 ${60 + tailWiggle} 20 ${45 + tailWiggle}`} 
            fill="none" 
            stroke={color} 
            strokeWidth="10" 
            strokeLinecap="round"
          />

          {/* Body */}
          <ellipse 
            cx="55" 
            cy={72 + bodyTranslateY} 
            rx={28 + breathing} 
            ry={(20 + breathing) * bodyScaleY} 
            fill={color} 
            className="transition-all duration-300"
          />

          {/* Back Leg 1 */}
          <g>
             {isClimbing ? (
               <path d={`M40 78 Q30 88 ${35 + climbLegWiggle} 94`} stroke={color} strokeWidth="9" fill="none" strokeLinecap="round" />
             ) : (
               <path d={`M40 78 L${35 + (isWalking || isPouncing ? walkLegWiggle : 0)} 96`} stroke={color} strokeWidth="9" strokeLinecap="round" />
             )}
             <circle cx={isClimbing ? 35 + climbLegWiggle : 35 + (isWalking || isPouncing ? walkLegWiggle : 0)} cy="96" r="2" fill="#FFB6C1" opacity="0.8" />
          </g>

          {/* Front Leg 1 */}
          <g>
            {isClimbing ? (
              <path d={`M70 78 Q80 88 ${75 + climbLegWiggle} 94`} stroke={color} strokeWidth="9" fill="none" strokeLinecap="round" />
            ) : (
              <path d={`M70 ${78 + (isStretching ? 5 : 0)} L${(isStretching ? 95 : 65 + (isWalking || isPouncing ? walkLegWiggle : 0))} 96`} stroke={color} strokeWidth="9" strokeLinecap="round" className="transition-all duration-500" />
            )}
            <circle cx={isClimbing ? 75 + climbLegWiggle : (isStretching ? 95 : 65 + (isWalking || isPouncing ? walkLegWiggle : 0))} cy="96" r="2" fill="#FFB6C1" opacity="0.8" />
          </g>

          {/* Head */}
          <g transform={`translate(${headTranslateX}, ${headTranslateY + (isNapping ? 2 : 0) + (isPouncing ? -10 : 0)})`} className="transition-all duration-500">
            <circle cx="78" cy="55" r="22" fill={color} />
            <circle cx="68" cy="62" r="4" fill="#FFB6C1" opacity="0.4" />
            <circle cx="88" cy="62" r="4" fill="#FFB6C1" opacity="0.4" />

            <path d="M62 40 L65 18 L78 35 Z" fill={color} />
            <path d="M85 35 L98 18 L102 40 Z" fill={color} />

            {/* Eyes */}
            {isNapping || isPlayingDead || isSniffing ? (
              <g transform="translate(78, 52)">
                <path d="M-10 0 Q-5 5 0 0" fill="none" stroke="black" strokeWidth="2" strokeLinecap="round" />
                <path d="M10 0 Q5 5 0 0" fill="none" stroke="black" strokeWidth="2" strokeLinecap="round" />
              </g>
            ) : isScratching ? (
              <g transform="translate(78, 52)">
                <path d="M-8 -3 L-2 3 M-8 3 L-2 -3" stroke="black" strokeWidth="3" strokeLinecap="round" />
                <path d="M8 -3 L2 3 M8 3 L2 -3" stroke="black" strokeWidth="3" strokeLinecap="round" />
              </g>
            ) : (
              <g transform="translate(78, 52)">
                <circle cx="-7" cy="0" r="4" fill="black" />
                <circle cx="7" cy="0" r="4" fill="black" />
                <circle cx="-8" cy="-1.5" r="1.5" fill="white" />
                <circle cx="6" cy="-1.5" r="1.5" fill="white" />
              </g>
            )}

            {/* Nose & Mouth */}
            <g transform="translate(78, 62)">
              <path d="M-2 -1 L0 1 L2 -1" fill="none" stroke="pink" strokeWidth="2" strokeLinecap="round" />
            </g>
          </g>

          {/* VFX */}
          {isPouncing && (
            <path d="M10 50 Q-10 50 -20 60" stroke="white" strokeWidth="2" strokeDasharray="5,5" className="animate-pulse" />
          )}
        </g>
      </svg>
    );
  }, [state, color, frame, direction, isLegendary]);

  return (
    <div
      onMouseDown={handleMouseDown}
      onClick={handleInteraction}
      className={`fixed z-[9999] cursor-grab active:cursor-grabbing select-none will-change-transform ${state === 'SCRATCHING' || state === 'CHASING_TAIL' || state === 'WIGGLING' ? 'vibrate' : ''}`}
      style={{
        left: pos.x,
        top: pos.y,
        width: SIZE,
        height: SIZE,
        transform: isZoomed ? 'scale(1.25)' : 'scale(1)',
        transition: ['DRAGGING', 'CHASING_TAIL', 'POUNCING'].includes(state) 
          ? 'transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275)' 
          : 'left 0.1s linear, top 0.1s linear, transform 0.3s ease-out'
      }}
    >
      <div className="relative w-full h-full group">
        {catSVG}

        <div className="absolute -top-10 left-1/2 -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity text-[10px] font-black text-white bg-orange-600 px-3 py-1 rounded-full pointer-events-none anime-font italic tracking-widest shadow-lg border border-white/20 whitespace-nowrap">
          {state === 'POUNCING' ? 'NYA BLAST!' : 
           state === 'SNIFFING' ? 'QUERYING...' : 
           state === 'STRETCHING' ? 'REFACTORING' : 
           state === 'WIGGLING' ? 'EXCITED!' : 
           state === 'CLIMBING' ? 'ELEMENT CLIMB!' : 'NEKO ARCHITECT'}
        </div>
      </div>
    </div>
  );
};

