import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';

type CatState = 
  | 'IDLE' | 'WALKING' | 'CLIMBING' | 'FALLING' | 'DRAGGING' 
  | 'SCRATCHING' | 'PLAYING_DEAD' | 'SITTING' | 'GROOMING' 
  | 'NAPPING' | 'CHASING_TAIL' | 'POUNCING' | 'SNIFFING' 
  | 'STRETCHING' | 'WIGGLING';

interface CatProps {
  id: number;
  color: string;
  initialX: number;
  initialY: number;
}

const Cat: React.FC<CatProps> = ({ color, initialX, initialY }) => {
  const [pos, setPos] = useState({ x: initialX, y: initialY });
  const [state, setState] = useState<CatState>('FALLING');
  const [direction, setDirection] = useState<1 | -1>(1);
  const [frame, setFrame] = useState(0);
  const [isLegendary, setIsLegendary] = useState(Math.random() > 0.9);
  const [isZoomed, setIsZoomed] = useState(false);

  const draggingRef = useRef(false);
  const requestRef = useRef<number | null>(null);
  const stateTimerRef = useRef<number | null>(null);
  const surfacesRef = useRef<DOMRect[]>([]);
  const targetSurfaceRef = useRef<DOMRect | null>(null);

  const SIZE = 90;
  const SPEED_BASE = (isLegendary ? 4.0 : 2.8) + Math.random();
  const [currentSpeed] = useState(SPEED_BASE);
  const GRAVITY = 7;

  const updateSurfaces = useCallback(() => {
    const elements = document.querySelectorAll('h1, h2, h3, button, a, img, .group, .p-8, .p-5, .bg-slate-900');
    const rects: DOMRect[] = [];
    elements.forEach((el) => {
      const rect = el.getBoundingClientRect();
      if (rect.width > 30 && rect.height > 20 && rect.top < window.innerHeight && rect.bottom > 0) {
        rects.push(rect);
      }
    });
    surfacesRef.current = rects;
  }, []);

  useEffect(() => {
    updateSurfaces();
    window.addEventListener('resize', updateSurfaces);
    window.addEventListener('scroll', updateSurfaces);
    const interval = setInterval(updateSurfaces, 3000);
    return () => {
      window.removeEventListener('resize', updateSurfaces);
      window.removeEventListener('scroll', updateSurfaces);
      clearInterval(interval);
    };
  }, [updateSurfaces]);

  useEffect(() => {
    const interval = setInterval(() => {
      setFrame(f => (f + 1) % 12);
    }, 70);
    return () => clearInterval(interval);
  }, []);

  const updatePhysics = useCallback(() => {
    if (draggingRef.current) return;

    setPos((prev) => {
      let { x, y } = prev;
      const sw = window.innerWidth;
      const sh = window.innerHeight;
      const screenFloor = sh - SIZE;

      let currentFloor = screenFloor;

      for (const rect of surfacesRef.current) {
        const isHorizontallyOver = (x + SIZE * 0.3 < rect.right) && (x + SIZE * 0.7 > rect.left);
        if (isHorizontallyOver) {
          const surfaceTop = rect.top - SIZE + 5;
          if (Math.abs(y - surfaceTop) < 12) {
            currentFloor = surfaceTop;
            break;
          }
        }
      }

      if (state === 'FALLING') {
        let landed = false;
        for (const rect of surfacesRef.current) {
          const surfaceTop = rect.top - SIZE + 5;
          const isHorizontallyOver = (x + SIZE * 0.3 < rect.right) && (x + SIZE * 0.7 > rect.left);
          if (y + GRAVITY >= surfaceTop && y < surfaceTop && isHorizontallyOver) landed = true;
        }
        if (landed || y + GRAVITY >= screenFloor) setState('IDLE');
        else y += GRAVITY;
      } else if (state === 'WALKING' || state === 'POUNCING') {
        const nextX = x + currentSpeed * direction * (state === 'POUNCING' ? 2.5 : 1);
        let hitWall = false;
        let wallRect: DOMRect | null = null;
        for (const rect of surfacesRef.current) {
          const isAtSameHeight = y + SIZE > rect.top + 15 && y < rect.bottom - 15;
          if (isAtSameHeight) {
            if (direction === 1 && nextX + SIZE >= rect.left && x + SIZE <= rect.left + 5) { hitWall = true; wallRect = rect; x = rect.left - SIZE; }
            else if (direction === -1 && nextX <= rect.right && x >= rect.right - 5) { hitWall = true; wallRect = rect; x = rect.right; }
          }
        }
        if (!hitWall && (nextX >= sw - SIZE || nextX <= 0)) hitWall = true;
        if (hitWall) {
          if (Math.random() < 0.75) { setState('CLIMBING'); targetSurfaceRef.current = wallRect; }
          else setDirection(direction === 1 ? -1 : 1);
        } else { x = nextX; if (y < currentFloor - 10) setState('FALLING'); }
      } else if (state === 'CLIMBING') {
        y -= currentSpeed * 0.7;
        if (targetSurfaceRef.current) {
          const rect = targetSurfaceRef.current;
          x = (direction === 1) ? rect.left - SIZE : rect.right;
          if (y <= rect.top - SIZE + 5) { y = rect.top - SIZE + 5; setState('WALKING'); targetSurfaceRef.current = null; }
        } else if (y <= 0) { y = 0; setState('FALLING'); }
      } else if (state === 'CHASING_TAIL') { x += Math.sin(frame) * 4; y += Math.cos(frame) * 4; }
      return { x, y };
    });
    requestRef.current = requestAnimationFrame(updatePhysics);
  }, [state, direction, currentSpeed, frame]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(updatePhysics);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [updatePhysics]);

  useEffect(() => {
    const changeStateRandomly = () => {
      const lockedStates: CatState[] = ['SCRATCHING', 'PLAYING_DEAD', 'CLIMBING', 'CHASING_TAIL', 'POUNCING', 'STRETCHING', 'WIGGLING', 'SNIFFING'];
      if (draggingRef.current || lockedStates.includes(state)) return;
      const allPossible: CatState[] = ['WALKING', 'WALKING', 'WALKING', 'IDLE', 'SITTING', 'GROOMING', 'NAPPING'];
      const next = allPossible[Math.floor(Math.random() * allPossible.length)];
      setState(next);
      if (next === 'WALKING') setDirection(Math.random() > 0.5 ? 1 : -1);
      stateTimerRef.current = window.setTimeout(changeStateRandomly, 3000 + Math.random() * 3000);
    };
    stateTimerRef.current = window.setTimeout(changeStateRandomly, 1000);
    return () => { if (stateTimerRef.current) clearTimeout(stateTimerRef.current); };
  }, [state]);

  const handleInteraction = () => {
    if (state === 'DRAGGING') return;
    setIsZoomed(true);
    setTimeout(() => setIsZoomed(false), 1000);
    setState('FALLING');
  };

  const catSVG = useMemo(() => {
    const isPlayingDead = state === 'PLAYING_DEAD';
    const isClimbing = state === 'CLIMBING';
    const isWiggling = state === 'WIGGLING';
    const tailWiggle = Math.sin(frame * 0.4) * (isWiggling ? 30 : 15);
    return (
      <svg viewBox="0 0 100 100" className={`w-full h-full pointer-events-none drop-shadow-md transition-transform duration-300 ${isWiggling ? 'animate-pulse' : ''}`}>
        <g transform={`scale(${direction}, 1) translate(${direction === -1 ? -100 : 0}, 0)`}>
          <g className="transition-transform duration-500 origin-center" style={{ transform: isClimbing ? `rotate(${-90}deg)` : isPlayingDead ? `rotate(180deg)` : 'rotate(0deg)' }}>
            <path d={`M30 75 Q15 ${60 + tailWiggle} 20 ${45 + tailWiggle}`} fill="none" stroke={color} strokeWidth="10" strokeLinecap="round" />
            <ellipse cx="55" cy="72" rx="28" ry="20" fill={color} />
            <path d="M40 78 L35 96" stroke={color} strokeWidth="9" strokeLinecap="round" />
            <path d="M70 78 L65 96" stroke={color} strokeWidth="9" strokeLinecap="round" />
            <circle cx="78" cy="55" r="22" fill={color} />
            <path d="M62 40 L65 18 L78 35 Z" fill={color} /><path d="M85 35 L98 18 L102 40 Z" fill={color} />
            <circle cx="71" cy="52" r="3" fill="black" /><circle cx="85" cy="52" r="3" fill="black" />
          </g>
        </g>
      </svg>
    );
  }, [state, color, frame, direction]);

  return (
    <div onMouseDown={() => setState('DRAGGING')} onClick={handleInteraction} className={`fixed z-[9999] cursor-grab active:cursor-grabbing select-none`} style={{ left: pos.x, top: pos.y, width: SIZE, height: SIZE, transform: isZoomed ? 'scale(1.3)' : 'scale(1)', transition: 'left 0.1s linear, top 0.1s linear, transform 0.3s ease-out' }}>
      <div className="relative w-full h-full group">
        {catSVG}
        <div className="absolute -top-10 left-1/2 -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity text-[10px] font-black text-white bg-blue-600 px-3 py-1 rounded-full pointer-events-none anime-font italic tracking-widest shadow-lg border border-white/20 whitespace-nowrap z-20">
          {state === 'POUNCING' ? 'EXECUTING...' : 
           state === 'SNIFFING' ? 'QUERYING...' : 
           state === 'STRETCHING' ? 'REFACTORING...' : 
           state === 'WIGGLING' ? 'COMPILED!' : 
           state === 'CLIMBING' ? 'UPLINKING...' : 'IDLE_DAEMON'}
        </div>
      </div>
    </div>
  );
};

export default Cat;

