            }
          }
        }

        if (!hitWall && (nextX >= sw - SIZE || nextX <= 0)) {
          hitWall = true;
          x = nextX <= 0 ? 0 : sw - SIZE;
        }

        if (hitWall) {
          if (Math.random() < 0.6) {
            setState('CLIMBING');
            targetSurfaceRef.current = wallRect;
          } else {
            setDirection(direction === 1 ? -1 : 1);
          }
        } else {
          x = nextX;
          if (y < currentFloor - 15) setState('FALLING');
        }
      } else if (state === 'CLIMBING') {
        y -= currentSpeed * 0.6;
        if (targetSurfaceRef.current) {
          const rect = targetSurfaceRef.current;
          x = direction === 1 ? rect.left - SIZE : rect.right;
          if (y <= rect.top - SIZE + 5) {
            y = rect.top - SIZE + 5;
            setState('WALKING');
            targetSurfaceRef.current = null;
          }
        } else if (y <= 0) {
          y = 0;
          setState('FALLING');
        }
      } else if (state === 'CHASING_TAIL') {
        x += Math.sin(frame * 0.5) * 5;
        y += Math.cos(frame * 0.5) * 5;
      }

      return { x, y };
    });
    requestRef.current = requestAnimationFrame(updatePhysics);
  }, [state, direction, currentSpeed, frame]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(updatePhysics);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [updatePhysics]);

  useEffect(() => {
    const changeStateRandomly = () => {
      const lockedStates: CatState[] = ['SCRATCHING', 'PLAYING_DEAD', 'CLIMBING', 'CHASING_TAIL', 'POUNCING', 'STRETCHING', 'WIGGLING', 'SNIFFING', 'GROOMING', 'NAPPING'];
      if (draggingRef.current || lockedStates.includes(state)) return;

      const allPossible: CatState[] = [
        'WALKING', 'WALKING', 'WALKING', 
        'IDLE', 'IDLE', 'SITTING', 
        'GROOMING', 'NAPPING', 
        'SNIFFING', 'STRETCHING', 'WIGGLING', 'POUNCING'
      ];

      const next = allPossible[Math.floor(Math.random() * allPossible.length)];
