        next === 'NAPPING' ? 8000 :
        next === 'SNIFFING' ? 2500 :
        next === 'STRETCHING' ? 3500 :
        next === 'WIGGLING' ? 2000 :
        next === 'POUNCING' ? 1200 : 0;

      if (revertTime > 0) {
        setTimeout(() => setState('IDLE'), revertTime);
      }

