    const isWiggling = state === 'WIGGLING';
    const isStretching = state === 'STRETCHING';
    const isSniffing = state === 'SNIFFING';
    const isNapping = state === 'NAPPING';
    const isPouncing = state === 'POUNCING';
    const isGrooming = state === 'GROOMING';

    const tailWiggle = Math.sin(frame * 0.5) * (isWiggling ? 35 : 15);
    const bodyScaleX = isStretching ? 1.4 : isWiggling ? 0.95 : 1;
