              <path d="M85 35 L102 15 L105 40 Z" fill={color} />

              {/* Blush */}
              <circle cx="68" cy="62" r="4" fill="#FFB6C1" opacity="0.4" />
              <circle cx="88" cy="62" r="4" fill="#FFB6C1" opacity="0.4" />

              {/* Eyes */}
              {isNapping || isPlayingDead ? (
                <g transform="translate(72, 55)">
                   <path d="M0 0 Q4 4 8 0" fill="none" stroke="#222" strokeWidth="2" strokeLinecap="round" />
                   <path d="M12 0 Q16 4 20 0" fill="none" stroke="#222" strokeWidth="2" strokeLinecap="round" />
                </g>
              ) : isWiggling ? (
                <g transform="translate(70, 52)">
                   <path d="M0 0 L6 6 M0 6 L6 0" stroke="#f43f5e" strokeWidth="2" />
                   <path d="M14 0 L20 6 M14 6 L20 0" stroke="#f43f5e" strokeWidth="2" />
                </g>
              ) : (
                <g>
                  <circle cx="71" cy="52" r="4" fill="#111" />
                  <circle cx="85" cy="52" r="4" fill="#111" />
                  <circle cx="72" cy="50" r="1.5" fill="white" />
                  <circle cx="86" cy="50" r="1.5" fill="white" />
                </g>
              )}

              {/* Mouth/Nose */}
              <path d="M76 65 Q78 68 80 65" fill="none" stroke="#111" strokeWidth="1.5" strokeLinecap="round" />
            </g>
          </g>
        </g>
      </svg>
    );
  }, [state, color, frame, direction, isLegendary]);

  return (
    <div 
      onMouseDown={() => setState('DRAGGING')} 
      onClick={handleInteraction} 
      className={`fixed z-[9999] cursor-grab active:cursor-grabbing select-none transition-transform duration-300`} 
      style={{ 
        left: pos.x, 
        top: pos.y, 
        width: SIZE, 
        height: SIZE, 
        transform: isZoomed ? 'scale(1.25)' : 'scale(1)',
        transition: 'left 0.1s linear, top 0.1s linear, transform 0.3s ease-out'
      }}
    >
      <div className="relative w-full h-full group">
