import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';

type BunnyState = 
  | 'IDLE' | 'HOPPING' | 'CLIMBING' | 'FALLING' | 'DRAGGING' 
  | 'SCRATCHING' | 'PLAYING_DEAD' | 'SITTING' | 'GROOMING' 
  | 'NAPPING' | 'CHASING_TAIL' | 'ZOOMIES' | 'TWITCHING' 
  | 'FLOPPING' | 'WIGGLING';

interface BunnyProps {
  id: number;
  color: string;
  initialX: number;
  initialY: number;
}

const Bunny: React.FC<BunnyProps> = ({ color, initialX, initialY }) => {
  const [pos, setPos] = useState({ x: initialX, y: initialY });
  const [state, setState] = useState<BunnyState>('FALLING');
  const [direction, setDirection] = useState<1 | -1>(1);
  const [frame, setFrame] = useState(0);
  const [isLegendary, setIsLegendary] = useState(Math.random() > 0.92);
  const [isZoomed, setIsZoomed] = useState(false);

  const draggingRef = useRef(false);
  const requestRef = useRef<number | null>(null);
  const stateTimerRef = useRef<number | null>(null);
  const surfacesRef = useRef<DOMRect[]>([]);
  const targetSurfaceRef = useRef<DOMRect | null>(null);

  const SIZE = 90;
  const SPEED_BASE = (isLegendary ? 4.5 : 2.8) + Math.random();
  const [currentSpeed] = useState(SPEED_BASE);
  const GRAVITY = 7;

  const updateSurfaces = useCallback(() => {
    const elements = document.querySelectorAll('h1, h2, h3, button, a, img, .group, .p-8, .p-5, .bg-slate-900');
    const rects: DOMRect[] = [];
    elements.forEach((el) => {
      const rect = el.getBoundingClientRect();
      if (rect.width > 30 && rect.height > 20 && rect.top < window.innerHeight && rect.bottom > 0) {
        rects.push(rect);
      }
    });
    surfacesRef.current = rects;
  }, []);

  useEffect(() => {
    updateSurfaces();
    window.addEventListener('resize', updateSurfaces);
    window.addEventListener('scroll', updateSurfaces);
    const interval = setInterval(updateSurfaces, 3000);
    return () => {
      window.removeEventListener('resize', updateSurfaces);
      window.removeEventListener('scroll', updateSurfaces);
      clearInterval(interval);
    };
  }, [updateSurfaces]);

  useEffect(() => {
    const interval = setInterval(() => {
      setFrame(f => (f + 1) % 24);
    }, 40);
    return () => clearInterval(interval);
  }, []);

  const updatePhysics = useCallback(() => {
    if (draggingRef.current) return;

    setPos((prev) => {
      let { x, y } = prev;
      const sw = window.innerWidth;
      const sh = window.innerHeight;
      const screenFloor = sh - SIZE;

      let currentFloor = screenFloor;

      for (const rect of surfacesRef.current) {
        const isHorizontallyOver = (x + SIZE * 0.3 < rect.right) && (x + SIZE * 0.7 > rect.left);
        if (isHorizontallyOver) {
          const surfaceTop = rect.top - SIZE + 5;
          if (Math.abs(y - surfaceTop) < 20) {
            currentFloor = surfaceTop;
            break;
          }
        }
      }

      // Parabolic Hop Math
      const hopPhase = (frame % 12) / 12; // 0 to 1
      const hopHeight = Math.sin(hopPhase * Math.PI) * 15;

      if (state === 'FALLING') {
        let landed = false;
        for (const rect of surfacesRef.current) {
          const surfaceTop = rect.top - SIZE + 5;
          const isHorizontallyOver = (x + SIZE * 0.3 < rect.right) && (x + SIZE * 0.7 > rect.left);
          if (y + GRAVITY >= surfaceTop && y < surfaceTop && isHorizontallyOver) {
            y = surfaceTop;
            landed = true;
            break;
          }
        }
        if (landed || y + GRAVITY >= screenFloor) {
          y = landed ? y : screenFloor;
          setState('IDLE');
        } else {
          y += GRAVITY;
        }
      } else if (state === 'HOPPING' || state === 'ZOOMIES') {
        const moveSpeed = state === 'ZOOMIES' ? currentSpeed * 2.5 : currentSpeed;
        const nextX = x + moveSpeed * direction;

        let hitWall = false;
        let wallRect: DOMRect | null = null;
        for (const rect of surfacesRef.current) {
          const isAtSameHeight = y + SIZE > rect.top + 10 && y < rect.bottom - 10;
          if (isAtSameHeight) {
            if (direction === 1 && nextX + SIZE >= rect.left && x + SIZE <= rect.left + 5) {
              hitWall = true;
              wallRect = rect;
              x = rect.left - SIZE;
            } else if (direction === -1 && nextX <= rect.right && x >= rect.right - 5) {
              hitWall = true;
              wallRect = rect;
              x = rect.right;
            }
          }
        }

        if (!hitWall && (nextX >= sw - SIZE || nextX <= 0)) {
          hitWall = true;
          x = nextX <= 0 ? 0 : sw - SIZE;
        }

        if (hitWall) {
          if (Math.random() < 0.4) {
            setState('CLIMBING');
            targetSurfaceRef.current = wallRect;
          } else {
            setDirection(direction === 1 ? -1 : 1);
          }
        } else {
          x = nextX;
          // Apply hop arc to Y
          y = currentFloor - hopHeight;
          if (y < currentFloor - 30 && state !== 'HOPPING' && state !== 'ZOOMIES') setState('FALLING');
        }
      } else if (state === 'CLIMBING') {
        y -= currentSpeed * 0.5;
        if (targetSurfaceRef.current) {
          const rect = targetSurfaceRef.current;
          x = direction === 1 ? rect.left - SIZE : rect.right;
          if (y <= rect.top - SIZE + 5) {
            y = rect.top - SIZE + 5;
            setState('HOPPING');
            targetSurfaceRef.current = null;
          }
        } else if (y <= 0) {
          y = 0;
          setState('FALLING');
        }
      }

      return { x, y };
    });
    requestRef.current = requestAnimationFrame(updatePhysics);
  }, [state, direction, currentSpeed, frame]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(updatePhysics);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [updatePhysics]);

  useEffect(() => {
    const changeStateRandomly = () => {
      const lockedStates: BunnyState[] = ['CLIMBING', 'ZOOMIES', 'FLOPPING', 'WIGGLING', 'TWITCHING', 'GROOMING', 'NAPPING'];
      if (draggingRef.current || lockedStates.includes(state)) return;

      const allPossible: BunnyState[] = [
        'HOPPING', 'HOPPING', 'HOPPING', 
        'IDLE', 'IDLE', 'SITTING', 
        'GROOMING', 'NAPPING', 
        'TWITCHING', 'FLOPPING', 'WIGGLING', 'ZOOMIES'
      ];

      const next = allPossible[Math.floor(Math.random() * allPossible.length)];
      setState(next);

      if (next === 'HOPPING') setDirection(Math.random() > 0.5 ? 1 : -1);

      const revertTime = 
        next === 'GROOMING' ? 3000 :
        next === 'NAPPING' ? 12000 :
        next === 'TWITCHING' ? 2500 :
        next === 'FLOPPING' ? 5000 :
        next === 'WIGGLING' ? 2000 :
        next === 'ZOOMIES' ? 2000 : 0;

      if (revertTime > 0) {
        setTimeout(() => setState('IDLE'), revertTime);
      }

      stateTimerRef.current = window.setTimeout(changeStateRandomly, 8000 + Math.random() * 7000);
    };

    stateTimerRef.current = window.setTimeout(changeStateRandomly, 2000);
    return () => { if (stateTimerRef.current) clearTimeout(stateTimerRef.current); };
  }, [state]);

  const handleInteraction = () => {
    if (state === 'DRAGGING') return;
    setIsZoomed(true);
    setTimeout(() => setIsZoomed(false), 800);

    const responses: BunnyState[] = ['WIGGLING', 'FLOPPING', 'FALLING', 'TWITCHING', 'ZOOMIES'];
    setState(responses[Math.floor(Math.random() * responses.length)]);
  };

  const bunnySVG = useMemo(() => {
    const isPlayingDead = state === 'PLAYING_DEAD';
    const isClimbing = state === 'CLIMBING';
    const isWiggling = state === 'WIGGLING';
    const isFlopping = state === 'FLOPPING';
    const isTwitching = state === 'TWITCHING';
    const isNapping = state === 'NAPPING';
    const isZoomies = state === 'ZOOMIES';
    const isHopping = state === 'HOPPING';

    const t = (frame / 24) * Math.PI * 2;
    const earTwitch = isTwitching ? Math.sin(t * 10) * 15 : isHopping ? Math.sin(t * 2) * 10 : 0;
    const bodyScaleX = isFlopping ? 1.5 : isWiggling ? 0.96 : 1;
    const bodyScaleY = isFlopping ? 0.6 : isWiggling ? 1.04 : 1;
    const noseTwitch = Math.sin(t * 8) * 2;

    const renderLeg = (startX: number, startY: number, phase: number, isFar: boolean = false) => {
      let endX = startX - 2;
      let endY = startY + 15;

      if (isHopping || isZoomies) {
        const speed = isZoomies ? 4 : 2;
        endX += Math.sin(t * speed + phase) * 8;
        endY -= Math.max(0, Math.cos(t * speed + phase) * 10);
      } else if (isClimbing) {
        endY -= 10 + Math.sin(t * 3 + phase) * 8;
      } else if (isFlopping) {
        endX += 12;
        endY += 2;
      }

      return (
        <g opacity={isFar ? 0.6 : 1}>
          <path 
            d={`M${startX} ${startY} L${endX} ${endY}`} 
            stroke={color} 
            strokeWidth="10" 
            strokeLinecap="round" 
            className="transition-all duration-75"
          />
        </g>
      );
    };

    return (
      <svg viewBox="0 0 100 100" className={`w-full h-full pointer-events-none drop-shadow-2xl transition-transform duration-300 ${isWiggling ? 'vibrate' : ''}`}>
        <g transform={`scale(${direction}, 1) translate(${direction === -1 ? -100 : 0}, 0)`}>
          <g className="transition-transform duration-500 origin-center" 
             style={{ transform: isClimbing ? `rotate(${-90}deg)` : isPlayingDead || isFlopping ? `rotate(90deg)` : 'rotate(0deg)' }}>

            {/* Round Fluffy Tail */}
            <circle cx="28" cy="72" r="8" fill={color} opacity="0.9" />

            {/* Legs */}
            {renderLeg(45, 75, Math.PI, true)}
            {renderLeg(65, 75, 0, true)}

            {/* Egg-shaped Body */}
            <ellipse 
              cx="55" 
              cy="72" 
              rx={30 * bodyScaleX} 
              ry={22 * bodyScaleY} 
              fill={color} 
              className="transition-all duration-500"
            />

            {renderLeg(40, 78, 0, false)}
            {renderLeg(70, 78, Math.PI, false)}

            {/* Head */}
            <g transform={`translate(0, ${isTwitching ? noseTwitch : 0})`} className="transition-transform duration-200">
              <circle cx="78" cy="55" r="21" fill={color} />

              {/* Long Bunny Ears */}
              <g transform={`rotate(${earTwitch}, 70, 40)`}>
                <ellipse cx="68" cy="25" rx="7" ry="22" fill={color} transform="rotate(-10, 68, 25)" />
                <ellipse cx="68" cy="25" rx="3" ry="15" fill="#FFB6C1" opacity="0.4" transform="rotate(-10, 68, 25)" />
              </g>
              <g transform={`rotate(${-earTwitch}, 85, 40)`}>
                <ellipse cx="88" cy="25" rx="7" ry="22" fill={color} transform="rotate(10, 88, 25)" />
                <ellipse cx="88" cy="25" rx="3" ry="15" fill="#FFB6C1" opacity="0.4" transform="rotate(10, 88, 25)" />
              </g>

              {/* Eyes */}
              {isNapping ? (
                <g transform="translate(72, 55)" stroke="#222" strokeWidth="2.5" fill="none">
                   <path d="M0 2 Q4 6 8 2" />
                   <path d="M12 2 Q16 6 20 2" />
                </g>
              ) : (
                <g>
                  <circle cx="71" cy="52" r="4.5" fill="#111" />
                  <circle cx="85" cy="52" r="4.5" fill="#111" />
                  <circle cx="72" cy="50" r="1.5" fill="white" />
                </g>
              )}

              {/* Twitching Nose */}
              <path d={`M76 ${62+noseTwitch} L78 ${65+noseTwitch} L80 ${62+noseTwitch}`} fill="none" stroke="#FFB6C1" strokeWidth="2" strokeLinecap="round" />
            </g>
          </g>
        </g>
      </svg>
    );
  }, [state, color, frame, direction]);

  return (
    <div 
      onMouseDown={() => {
        draggingRef.current = true;
        setState('DRAGGING');
      }}
      onMouseUp={() => {
        draggingRef.current = false;
        setState('FALLING');
      }}
      onClick={handleInteraction} 
      className={`fixed z-[9999] cursor-grab active:cursor-grabbing select-none`} 
      style={{ 
        left: pos.x, 
        top: pos.y, 
        width: SIZE, 
        height: SIZE, 
        transform: isZoomed ? 'scale(1.2)' : 'scale(1)',
        transition: 'left 0.1s linear, top 0.1s linear, transform 0.3s ease-out'
      }}
    >
      <div className="relative w-full h-full group">
        {bunnySVG}

        <div className="absolute -top-14 left-1/2 -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-all duration-300 scale-75 group-hover:scale-100 text-[10px] font-black text-white bg-orange-600 px-4 py-1.5 rounded-full pointer-events-none anime-font italic tracking-widest shadow-2xl border-2 border-white/30 whitespace-nowrap z-20">
          {state === 'ZOOMIES' ? 'MAX_THROUGHPUT_ZOOM!' : 
           state === 'TWITCHING' ? 'QUERYING_DOM...' : 
           state === 'FLOPPING' ? 'ASYNC_REFACTOR_FLOP' : 
           state === 'WIGGLING' ? 'UPLINK_STABLE!' : 
           state === 'HOPPING' ? 'HOPPING_TO_CLOUD...' : 
           state === 'NAPPING' ? 'BURROW_MODE_ACTIVE' : 'BUNNY_DAEMON'}
        </div>

        {isLegendary && (
          <div className="absolute -bottom-2 right-0 bg-blue-500 text-white text-[8px] px-1.5 py-0.5 rounded font-black tracking-tighter border border-white/20 animate-bounce shadow-lg">
            LEGENDARY_BUN
          </div>
        )}
      </div>
    </div>
  );
};

