        endY -= Math.max(0, Math.cos(t * speedMult + phase) * 8);
        toeBeanVisible = cycle < -0.5;
      } else if (isClimbing) {
        const cycle = Math.sin(t * 2 + phase);
        endY -= 10 + cycle * 8;
        endX += cycle * 4;
        toeBeanVisible = true;
      } else if (isStretching) {
        endX += 15;
        endY += 4;
      }

      return (
        <g opacity={isFar ? 0.6 : 1}>
          <path 
            d={`M${startX} ${startY} L${endX} ${endY}`} 
            stroke={isFar ? '#00000033' : 'none'} 
            strokeWidth="11" 
            strokeLinecap="round" 
            className="transition-all duration-75"
          />
          <path 
            d={`M${startX} ${startY} L${endX} ${endY}`} 
            stroke={color} 
            strokeWidth="9" 
            strokeLinecap="round" 
            className="transition-all duration-75"
          />
          {toeBeanVisible && (
            <circle cx={endX} cy={endY} r="3" fill="#FFB6C1" opacity="0.6" />
          )}
        </g>
      );
    };

    return (
      <svg viewBox="0 0 100 100" className={`w-full h-full pointer-events-none drop-shadow-2xl transition-transform duration-300 ${isWiggling ? 'vibrate' : ''}`}>
        <g transform={`scale(${direction}, 1) translate(${direction === -1 ? -100 : 0}, 0)`}>
          <g className="transition-transform duration-500 origin-center" 
             style={{ transform: isClimbing ? `rotate(${-90}deg)` : isPlayingDead ? `rotate(180deg)` : 'rotate(0deg)' }}>

            {/* Tail */}
            <path 
              d={`M30 75 Q8 ${60 + tailWiggle} 12 ${35 + tailWiggle}`} 
              fill="none" 
              stroke={color} 
              strokeWidth="10" 
              strokeLinecap="round" 
              className="transition-all duration-300"
            />

            {/* Far Legs */}
            {renderLeg(45, 75, Math.PI, true)}
            {renderLeg(65, 75, 0, true)}

            {/* Body */}
            <ellipse 
              cx="55" 
              cy="72" 
              rx={28 * bodyScaleX} 
              ry={20 * bodyScaleY} 
              fill={color} 
              className="transition-all duration-500"
            />

            {/* Near Legs */}
            {renderLeg(40, 78, 0, false)}
            {renderLeg(70, 78, Math.PI, false)}

            {/* Head */}
            <g transform={`translate(${sniffOffset}, ${sniffOffset * 0.5})`} className="transition-transform duration-200">
              <circle cx="78" cy="55" r="23" fill={color} />

              {/* Ears */}
              <path d="M62 40 L58 12 L78 35 Z" fill={color} />
              <path d="M85 35 L102 12 L105 40 Z" fill={color} />

              {/* Blush */}
              <circle cx="68" cy="62" r="4" fill="#FFB6C1" opacity="0.3" />
              <circle cx="88" cy="62" r="4" fill="#FFB6C1" opacity="0.3" />

              {/* Eyes */}
              {isNapping || isPlayingDead ? (
                <g transform="translate(72, 55)" stroke="#222" strokeWidth="2.5" fill="none">
                   <path d="M0 2 Q4 6 8 2" strokeLinecap="round" />
                   <path d="M12 2 Q16 6 20 2" strokeLinecap="round" />
                </g>
              ) : isWiggling ? (
                <g transform="translate(70, 52)">
                   <path d="M0 0 L6 6 M0 6 L6 0" stroke="#f43f5e" strokeWidth="3" strokeLinecap="round" />
                   <path d="M14 0 L20 6 M14 6 L20 0" stroke="#f43f5e" strokeWidth="3" strokeLinecap="round" />
                </g>
              ) : (
                <g>
                  <circle cx="71" cy="52" r="5" fill="#111" />
                  <circle cx="85" cy="52" r="5" fill="#111" />
                  <circle cx="72" cy="50" r="2" fill="white" />
                  <circle cx="86" cy="50" r="2" fill="white" />
                </g>
              )}

              {/* Mouth/Nose */}
              <path d="M75 64 Q78 67 81 64" fill="none" stroke="#111" strokeWidth="2" strokeLinecap="round" />
            </g>
          </g>
        </g>
      </svg>
    );
  }, [state, color, frame, direction]);

  return (
    <div 
      onMouseDown={() => {
        draggingRef.current = true;
        setState('DRAGGING');
      }}
      onMouseUp={() => {
        draggingRef.current = false;
        setState('FALLING');
      }}
      onClick={handleInteraction} 
      className={`fixed z-[9999] cursor-grab active:cursor-grabbing select-none`} 
      style={{ 
        left: pos.x, 
        top: pos.y, 
        width: SIZE, 
        height: SIZE, 
        transform: isZoomed ? 'scale(1.25)' : 'scale(1)',
        transition: 'left 0.1s linear, top 0.1s linear, transform 0.3s ease-out'
      }}
    >
      <div className="relative w-full h-full group">
        {catSVG}

        {/* Status Bubble */}
        <div className="absolute -top-14 left-1/2 -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-all duration-300 scale-75 group-hover:scale-100 text-[10px] font-black text-white bg-blue-600 px-4 py-1.5 rounded-full pointer-events-none anime-font italic tracking-widest shadow-2xl border-2 border-white/30 whitespace-nowrap z-20">
          {state === 'POUNCING' ? 'EXECUTING_QUICK_FIX...' : 
           state === 'SNIFFING' ? 'QUERYING_SELECTOR...' : 
           state === 'STRETCHING' ? 'REFACTORING_CORE...' : 
           state === 'WIGGLING' ? 'SYSTEM_STABLE!' : 
           state === 'CLIMBING' ? 'UPLINKING_TO_CLOUD...' : 
           state === 'NAPPING' ? 'SLEEP_MODE_ACTIVE' :
           state === 'GROOMING' ? 'GARBAGE_COLLECTION' : 'IDLE_DAEMON'}
        </div>

        {isLegendary && (
          <div className="absolute -bottom-2 right-0 bg-orange-500 text-white text-[8px] px-1.5 py-0.5 rounded font-black tracking-tighter border border-white/20 animate-bounce shadow-lg">
            S-RANK
          </div>
        )}
      </div>
    </div>
  );
};

