                          <div className="flex flex-wrap gap-2">
                            {proj.tech.map(t => (
                              <span key={t} className="text-[10px] font-mono text-slate-400 uppercase">{t}</span>
                            ))}
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

