        const nextX = x + moveSpeed * direction;

        let hitEdge = false;
        let wallRect: DOMRect | null = null;

        // Check for element side borders (walls)
        for (const rect of surfacesRef.current) {
          const isAtSameHeight = y + SIZE > rect.top + 2 && y < rect.bottom - 2;
          if (isAtSameHeight) {
            if (direction === 1 && nextX + SIZE >= rect.left && x + SIZE <= rect.left + 5) {
              hitEdge = true;
              wallRect = rect;
              x = rect.left - SIZE;
            } else if (direction === -1 && nextX <= rect.right && x >= rect.right - 5) {
              hitEdge = true;
              wallRect = rect;
              x = rect.right;
            }
          }
        }

        // Screen edges are also walls
        if (!hitEdge && (nextX >= sw - SIZE || nextX <= 0)) {
          hitEdge = true;
          x = nextX <= 0 ? 0 : sw - SIZE;
        }

        if (hitEdge) {
          // If hit a wall/border, climb it
          setState('CLIMBING');
          targetSurfaceRef.current = wallRect;
        } else {
          x = nextX;
          // Check if we walked off the current element's border
          let remainsOnSurface = false;
          if (isOnFloor) {
            remainsOnSurface = true;
          } else {
            for (const rect of surfacesRef.current) {
              const isOver = (x + SIZE * 0.2 < rect.right) && (x + SIZE * 0.8 > rect.left);
              if (isOver && Math.abs(y - (rect.top - SIZE + 4)) < 12) {
                remainsOnSurface = true;
                break;
              }
            }
          }
          if (!remainsOnSurface) setState('FALLING');
        }
      } else if (state === 'CLIMBING') {
        // Vertical movement scaling borders
        y -= currentSpeed * 0.9;

        if (targetSurfaceRef.current) {
          const rect = targetSurfaceRef.current;
          // Stay attached to the border while climbing
          x = direction === 1 ? rect.left - SIZE : rect.right;

          if (y <= rect.top - SIZE + 4) {
            y = rect.top - SIZE + 4;
            setState('WALKING');
            targetSurfaceRef.current = null;
          }
        } else {
          // Climbing screen edge or undefined wall
          if (y <= 0) {
            y = 0;
            setDirection(direction === 1 ? -1 : 1);
            setState('FALLING');
          }
          // Small chance to stop climbing and jump off
          if (Math.random() < 0.01) setState('FALLING');
        }
      }

      return { x, y };
    });
    requestRef.current = requestAnimationFrame(updatePhysics);
  }, [state, direction, currentSpeed]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(updatePhysics);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [updatePhysics]);

  const changeStateRandomly = useCallback(() => {
    const lockedStates: CatState[] = ['CLIMBING', 'POUNCING', 'WIGGLING', 'DRAGGING'];
    if (draggingRef.current || lockedStates.includes(state)) return;

    // NO RESTING ALLOWED. Constant movement or active interaction only.
    const behaviors: CatState[] = ['WALKING', 'WALKING', 'WALKING', 'POUNCING', 'SNIFFING', 'STRETCHING', 'PLAYING_DEAD', 'WIGGLING'];
    const next = behaviors[Math.floor(Math.random() * behaviors.length)];
    setState(next);

    if (next === 'WALKING' || next === 'POUNCING') setDirection(Math.random() > 0.5 ? 1 : -1);

    const duration = 
      next === 'SNIFFING' ? 1000 :
      next === 'STRETCHING' ? 1200 :
      next === 'WIGGLING' ? 900 :
      next === 'PLAYING_DEAD' ? 1800 :
      next === 'POUNCING' ? 1100 : 0;

    if (duration > 0) {
      setTimeout(() => { if (!draggingRef.current) setState('WALKING'); }, duration);
      stateTimerRef.current = window.setTimeout(changeStateRandomly, duration + 800);
    } else {
      stateTimerRef.current = window.setTimeout(changeStateRandomly, 5000 + Math.random() * 5000);
    }
  }, [state]);

  useEffect(() => {
    stateTimerRef.current = window.setTimeout(changeStateRandomly, 1500);
    return () => { if (stateTimerRef.current) clearTimeout(stateTimerRef.current); };
  }, [changeStateRandomly]);

  const handleInteraction = () => {
    if (state === 'DRAGGING') return;

    setIsZoomed(true);
    setTimeout(() => setIsZoomed(false), 700);

    // Trigger an "other" behavior on click
    const interactiveBehaviors: CatState[] = ['POUNCING', 'SNIFFING', 'STRETCHING', 'WIGGLING', 'PLAYING_DEAD'];
    const next = interactiveBehaviors[Math.floor(Math.random() * interactiveBehaviors.length)];
    setState(next);

    if (stateTimerRef.current) clearTimeout(stateTimerRef.current);

    const duration = 
      next === 'SNIFFING' ? 1500 :
      next === 'STRETCHING' ? 1600 :
      next === 'WIGGLING' ? 1200 :
      next === 'PLAYING_DEAD' ? 2500 :
      next === 'POUNCING' ? 1800 : 1000;

    setTimeout(() => { if (!draggingRef.current) setState('WALKING'); }, duration);
    stateTimerRef.current = window.setTimeout(changeStateRandomly, duration + 1000);
  };

  const catSVG = useMemo(() => {
    const isPlayingDead = state === 'PLAYING_DEAD';
    const isClimbing = state === 'CLIMBING';
    const isWiggling = state === 'WIGGLING';
    const isStretching = state === 'STRETCHING';
    const isSniffing = state === 'SNIFFING';
    const isPouncing = state === 'POUNCING';
    const isWalking = state === 'WALKING';

    const t = (frame / 24) * Math.PI * 2;
    const tailWiggle = Math.sin(t * 1.5) * (isWiggling ? 35 : isWalking ? 12 : 6);
    const bodyScaleX = isStretching ? 1.4 : isWiggling ? 0.95 : 1;
    const bodyScaleY = isStretching ? 0.8 : isWiggling ? 1.05 : 1;
    const sniffOffset = isSniffing ? Math.sin(t * 5) * 4 : 0;

    const renderLeg = (startX: number, startY: number, phase: number, isFar: boolean = false) => {
      let endX = startX - 5;
      let endY = startY + 18;

      if (isWalking || isPouncing) {
        const speed = isPouncing ? 4 : 2;
        endX += Math.sin(t * speed + phase) * 12;
        endY -= Math.max(0, Math.cos(t * speed + phase) * 10);
      } else if (isClimbing) {
        endY -= 14 + Math.sin(t * 3 + phase) * 8;
        endX += Math.sin(t * 3 + phase) * 5;
      } else if (isStretching) {
